import pytest
from solution import topo_sort


def _is_valid_topo_order(num_nodes, edges, order):
    """Check that order is a valid topological sort."""
    if sorted(order) != list(range(num_nodes)):
        return False
    pos = {node: i for i, node in enumerate(order)}
    for a, b in edges:
        if pos[b] > pos[a]:  # b must come before a
            return False
    return True


def test_linear_chain():
    result = topo_sort(3, [[1, 0], [2, 1]])
    assert _is_valid_topo_order(3, [[1, 0], [2, 1]], result)


def test_diamond():
    edges = [[1, 0], [2, 0], [3, 1], [3, 2]]
    result = topo_sort(4, edges)
    assert _is_valid_topo_order(4, edges, result)


def test_cycle_raises():
    with pytest.raises(ValueError):
        topo_sort(2, [[0, 1], [1, 0]])


def test_self_loop_raises():
    with pytest.raises(ValueError):
        topo_sort(1, [[0, 0]])


def test_empty_graph():
    result = topo_sort(0, [])
    assert result == []


def test_single_node():
    result = topo_sort(1, [])
    assert result == [0]


def test_no_edges():
    result = topo_sort(4, [])
    assert sorted(result) == [0, 1, 2, 3]


def test_disconnected_components():
    edges = [[1, 0], [3, 2]]
    result = topo_sort(4, edges)
    assert _is_valid_topo_order(4, edges, result)


def test_larger_cycle():
    with pytest.raises(ValueError):
        topo_sort(3, [[0, 1], [1, 2], [2, 0]])


def test_complex_dag():
    edges = [[2, 0], [2, 1], [3, 2], [4, 2], [5, 3], [5, 4]]
    result = topo_sort(6, edges)
    assert _is_valid_topo_order(6, edges, result)


def test_single_dependency():
    result = topo_sort(2, [[1, 0]])
    assert result == [0, 1]


def test_multiple_roots():
    edges = [[2, 0], [2, 1]]
    result = topo_sort(3, edges)
    assert _is_valid_topo_order(3, edges, result)
    assert result[-1] == 2  # 2 depends on 0 and 1

